#!/usr/bin/env bash
# Add the AboutLibraries Gradle plugin to the generated Android project.
#
# src-tauri/gen/android is regenerated by `tauri android init`, so the app
# module cannot carry the plugin itself. Run this after every init. The
# plugin writes res/raw/aboutlibraries.json (every Maven library in the APK
# with its license text) from the resolved release graph plus the texts in
# licenses/android/, and fails the build on a library without a license or
# with one outside the allow-list. LicensesActivity (in the share-target
# plugin) shows it. Usage:
#   scripts/add-android-notices.sh [src-tauri/gen/android]
set -euo pipefail

readonly ABOUTLIBRARIES_VERSION="15.2.0"
readonly PLUGIN_LINE="    id(\"com.mikepenz.aboutlibraries.plugin.android\") version \"$ABOUTLIBRARIES_VERSION\""
readonly MARKER="// Third-party notices (scripts/add-android-notices.sh)"

GEN="${1:-src-tauri/gen/android}"
APP_GRADLE="$GEN/app/build.gradle.kts"

die() { echo "add-android-notices.sh: $*" >&2; exit 1; }

[ -f "$APP_GRADLE" ] || die "$APP_GRADLE not found; run 'tauri android init' first"
if grep -qF "$MARKER" "$APP_GRADLE"; then
	echo "AboutLibraries is already configured in $APP_GRADLE"
	exit 0
fi

# The plugins block of Tauri's template ends its fixed list with id("rust").
grep -qx '    id("rust")' "$APP_GRADLE" || die "no id(\"rust\") line in the plugins block of $APP_GRADLE"
sed -i "s|^    id(\"rust\")\$|&\n$PLUGIN_LINE|" "$APP_GRADLE"
grep -qxF "$PLUGIN_LINE" "$APP_GRADLE" || die "could not add the plugin to $APP_GRADLE"

# Offline and reproducible: license texts come from licenses/android/licenses,
# hand-maintained entries from licenses/android/libraries (paths relative to
# the app module, src-tauri/gen/android/app).
cat >>"$APP_GRADLE" <<EOF

$MARKER
aboutLibraries {
    offlineMode = true
    collect {
        configPath = file("../../../../licenses/android")
        fetchRemoteLicense = false
        fetchRemoteFunding = false
    }
    library {
        requireLicense = true
    }
    license {
        strictMode = com.mikepenz.aboutlibraries.plugin.StrictMode.FAIL
        allowedLicenses.addAll("Apache-2.0", "MIT", "BSD-2-Clause")
    }
}
EOF
echo "Added AboutLibraries $ABOUTLIBRARIES_VERSION to $APP_GRADLE"
